import * as React from "react";
import { CalendarIcon } from "lucide-react";
import type { DateRange } from "react-day-picker";

import { cn } from "@/lib/utils";
import { Button } from "./button";
import { Calendar } from "./calendar";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

/**
 * figma: Date Picker — a composition of Popover + Calendar, exposed as a
 * component for the common cases.
 *
 * Recipes: Basic · Range Picker · Date of Birth (captionLayout="dropdown") ·
 * Input · Time Picker · Natural Language Picker (parse with chrono-node and
 * feed the result to `value`) · RTL.
 *
 * For anything beyond these, compose Popover + Calendar directly — that is
 * what the kit's more elaborate examples do.
 */
function formatDate(date: Date | undefined, locale?: string) {
  return date
    ? date.toLocaleDateString(locale, { day: "numeric", month: "long", year: "numeric" })
    : "";
}

function DatePicker({
  value,
  onValueChange,
  placeholder = "Pick a date",
  captionLayout = "label",
  disabled,
  className,
  locale,
  ...calendarProps
}: Omit<React.ComponentProps<typeof Calendar>, "mode" | "selected" | "onSelect" | "disabled"> & {
  value?: Date;
  onValueChange?: (date: Date | undefined) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  locale?: string;
}) {
  const [open, setOpen] = React.useState(false);
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          disabled={disabled}
          data-slot="date-picker-trigger"
          data-empty={!value}
          className={cn("w-full justify-between font-normal data-[empty=true]:text-muted-foreground", className)}
        >
          {value ? formatDate(value, locale) : placeholder}
          <CalendarIcon data-icon="inline-end" />
        </Button>
      </PopoverTrigger>
      <PopoverContent data-slot="date-picker-content" className="w-auto p-0" align="start">
        <Calendar
          mode="single"
          selected={value}
          captionLayout={captionLayout}
          onSelect={(date) => {
            onValueChange?.(date);
            setOpen(false);
          }}
          {...calendarProps}
        />
      </PopoverContent>
    </Popover>
  );
}

function DateRangePicker({
  value,
  onValueChange,
  placeholder = "Pick a date range",
  disabled,
  className,
  locale,
  ...calendarProps
}: Omit<React.ComponentProps<typeof Calendar>, "mode" | "selected" | "onSelect" | "disabled"> & {
  value?: DateRange;
  onValueChange?: (range: DateRange | undefined) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  locale?: string;
}) {
  const [open, setOpen] = React.useState(false);
  const label = value?.from
    ? value.to
      ? `${formatDate(value.from, locale)} – ${formatDate(value.to, locale)}`
      : formatDate(value.from, locale)
    : "";

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          disabled={disabled}
          data-slot="date-range-picker-trigger"
          data-empty={!value?.from}
          className={cn("w-full justify-between font-normal data-[empty=true]:text-muted-foreground", className)}
        >
          {label || placeholder}
          <CalendarIcon data-icon="inline-end" />
        </Button>
      </PopoverTrigger>
      <PopoverContent data-slot="date-range-picker-content" className="w-auto p-0" align="start">
        <Calendar
          mode="range"
          selected={value}
          onSelect={onValueChange}
          numberOfMonths={2}
          {...calendarProps}
        />
      </PopoverContent>
    </Popover>
  );
}

export { DatePicker, DateRangePicker, formatDate };
